import { Audio, Sequence, staticFile } from "remotion";

export type SfxName =
  | "whoosh"
  | "whoosh-short"
  | "swish-reverse"
  | "impact"
  | "sub-drop"
  | "click"
  | "tick"
  | "pop"
  | "riser"
  | "shimmer"
  | "type"
  | "glitch";

/** One sound effect placed at a frame. Files live in public/sfx (generated by scripts/make-sfx.py). */
export const Sfx: React.FC<{ name: SfxName; at: number; volume?: number }> = ({ name, at, volume = 0.6 }) => (
  <Sequence from={at} layout="none">
    <Audio src={staticFile(`sfx/${name}.wav`)} volume={volume} />
  </Sequence>
);

/** Background music bed from public/music, faded in and out. */
export const Music: React.FC<{ file: string; durationInFrames: number; volume?: number; fade?: number; startFrom?: number }> = ({
  file,
  durationInFrames,
  volume = 0.5,
  fade = 20,
  startFrom = 0,
}) => (
  <Audio
    src={staticFile(`music/${file}`)}
    startFrom={startFrom}
    volume={(f) => volume * Math.min(1, f / fade, (durationInFrames - f) / fade)}
  />
);
